#include "extension.h"
#include <string.h>
static unsigned rd16(const unsigned char*p){return (unsigned)p[0]|(unsigned)p[1]<<8;}
static uint32_t rd32(const unsigned char*p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static void wr16(unsigned char*p,unsigned x){p[0]=(unsigned char)x;p[1]=(unsigned char)(x>>8);}
static void wr32(unsigned char*p,uint32_t x){for(unsigned i=0;i<4;i++)p[i]=(unsigned char)(x>>(8*i));}
static int canonical(const CEProgram*p){unsigned h[CE_CODE];if(!ce_verify(p,h))return 0;for(unsigned f=0;f<p->functions;f++){const CEFunc *g=&p->fn[f];size_t z=0;while(z<16&&g->name[z]){unsigned c=(unsigned char)g->name[z];if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||c=='_'||(z&&c>='0'&&c<='9')))return 0;z++;}if(!z||z==16)return 0;for(size_t j=z;j<16;j++)if(g->name[j])return 0;for(unsigned j=g->locals;j<CE_LOCALS;j++)if(g->types[j])return 0;for(unsigned j=0;j<f;j++)if(!strcmp(g->name,p->fn[j].name))return 0;}
 if(strcmp(p->fn[p->functions-1].name,"main"))return 0;for(unsigned i=0;i<p->count;i++){CEIns a=p->code[i];if(a.op!=CE_CONST&&a.op!=CE_LOAD&&a.op!=CE_STORE&&a.op!=CE_JZ&&a.op!=CE_JMP&&a.op!=CE_CALL&&a.op!=CE_TO_U32&&a.arg)return 0;}return 1;}
int ce_pack(const CEProgram*p,unsigned char*out,size_t cap,size_t*written){unsigned char b[4252]={0};if(!out||!written||!canonical(p))return 0;size_t n=8+37*p->functions+8*p->count;if(cap<n)return 0;memcpy(b,"CEIR",4);b[4]=1;b[5]=(unsigned char)p->functions;wr16(b+6,p->count);size_t at=8;for(unsigned f=0;f<p->functions;f++){const CEFunc*g=&p->fn[f];wr16(b+at,g->begin);wr16(b+at+2,g->end);b[at+4]=(unsigned char)g->locals;for(unsigned j=0;j<16;j++)b[at+5+j]=(unsigned char)g->types[j];memcpy(b+at+21,g->name,16);at+=37;}for(unsigned i=0;i<p->count;i++){b[at]=(unsigned char)p->code[i].op;wr32(b+at+4,p->code[i].arg);at+=8;}memcpy(out,b,n);*written=n;return 1;}
int ce_unpack(const unsigned char*b,size_t n,CEProgram*out){CEProgram p={0};if(!b||!out||n<8||memcmp(b,"CEIR",4)||b[4]!=1)return 0;p.functions=b[5];p.count=rd16(b+6);if(!p.functions||p.functions>4||!p.count||p.count>512||n!=8+37*p.functions+8*p.count)return 0;size_t at=8;for(unsigned f=0;f<p.functions;f++){CEFunc*g=&p.fn[f];g->begin=rd16(b+at);g->end=rd16(b+at+2);g->locals=b[at+4];for(unsigned j=0;j<16;j++)g->types[j]=b[at+5+j];memcpy(g->name,b+at+21,16);at+=37;}for(unsigned i=0;i<p.count;i++){if(b[at+1]||b[at+2]||b[at+3])return 0;p.code[i]=(CEIns){b[at],rd32(b+at+4)};at+=8;}if(!canonical(&p))return 0;*out=p;return 1;}
